import { SteppedScale } from "./util";
/**
 * Domain keys used internally to identify numeric dimensions to scale.
 * Keep this flexible so charts/plots can introduce new domains like "r" or "yStacked".
 * @internal
 */
export type AxisDomainKey = "x" | "y" | "xStacked" | "yStacked" | "r" | (string & {});
/**
 * Simple min/max extent for a numeric domain. Optionally with desired step specified
 * @internal
 */
export interface DomainExtent {
    min: number;
    max: number;
    step?: number;
    stepCount?: number;
    minLimit?: number;
    maxLimit?: number;
}
/**
 * Extents by domain key.
 * @internal
 */
export type DomainExtentMap = Partial<Record<AxisDomainKey, DomainExtent>>;
/**
 * Optional per-domain overrides (typically derived from user axis definitions).
 * If provided, these are applied after merging extents.
 * @internal
 */
export type DomainOverrideMap = Partial<Record<AxisDomainKey, {
    min?: number;
    max?: number;
    step?: number;
}>>;
/**
 * Output: scales by domain.
 * @internal
 */
export type DomainScaleMap = Partial<Record<AxisDomainKey, SteppedScale>>;
/**
 * Merge multiple extent maps into one by taking:
 * - min = minimum of mins
 * - max = maximum of maxes
 *
 * Any invalid/non-finite extents are ignored.
 * @internal
 */
export declare function mergeDomainExtents(extentsList: Array<DomainExtentMap | null | undefined>): DomainExtentMap;
/**
 * Apply overrides (min/max) to merged extents.
 * - If override.min is set: extent.min = override.min
 * - If override.max is set: extent.max = override.max
 * - If overrides make min > max, they are swapped to keep a valid extent.
 * @internal
 */
export declare function applyDomainOverrides(extents: DomainExtentMap, overrides?: DomainOverrideMap): DomainExtentMap;
/**
 * Build SteppedScale objects for each domain present in `extents`.
 *
 * Notes:
 * - Uses the existing $autoCalculateChartScale(min, max) helper.
 * - Skips domains whose extents are invalid.
 * @internal
 */
export declare function buildDomainScales(extents: DomainExtentMap): DomainScaleMap;
/**
 * Convenience: merge → override → build scales.
 * @internal
 */
export declare function computeDomainScales(params: {
    extentsList: Array<DomainExtentMap | null | undefined>;
    overrides?: DomainOverrideMap;
}): {
    extents: DomainExtentMap;
    scales: DomainScaleMap;
};
